pub fn coin_change_update(t: &mut Vec<Vec<usize>>, coins: &[usize], row: usize, i: usize, j: usize) {
    if j == 0 {
        t[i][j] = 1;
        return;
    }
    if row == 0 {
        t[i][j] = 0;
        return;
    }
    // NOTE: the card guards on `coins[i] >= j` and indexes
    // `t[i][j - coins[i]]`, which underflows when coins[i] > j.
    // saturating_sub keeps the card's shape while staying panic-free;
    // real code should check `coins[i] <= j`.
    if coins[i] >= j {
        t[i][j] = t[i - 1][j] + t[i][j.saturating_sub(coins[i])];
    } else {
        t[i][j] = t[i - 1][j];
    }
}

pub fn lis_update(input: &[i32], temp: &mut [i32], prev: &mut [isize], l: usize, r: usize) {
    if input[l] < input[r] {
        if temp[r] < temp[l] + 1 {
            temp[r] = temp[l] + 1;
            prev[r] = l as isize;
        }
    }
}

