impl Solution {
    /// Formats `license_key` into groups of `k` characters (first group may
    /// be shorter), upper-casing letters and reinserting dashes.
    pub fn format_license_key(license_key: &str, k: usize) -> Result<String, String> {
        if license_key.is_empty() {
            return Err("license_key must not be empty".to_string());
        }
        if k == 0 {
            return Err("k must be positive".to_string());
        }
        let mut out: Vec<char> = Vec::new();
        let mut num_chars = 0;
        for ch in license_key.chars().rev() {
            if ch == '-' {
                continue;
            }
            num_chars += 1;
            out.push(ch.to_ascii_uppercase());
            if num_chars >= k {
                out.push('-');
                num_chars = 0;
            }
        }
        if out.last() == Some(&'-') {
            out.pop();
        }
        out.reverse();
        Ok(out.into_iter().collect())
    }
}

#[test]
fn test_format_license_key() {
    assert_eq!(Solution::format_license_key("---", 3), Ok(String::new()));
    assert_eq!(
        Solution::format_license_key("2-4A0r7-4k", 3),
        Ok("24-A0R-74K".to_string())
    );
    assert_eq!(
        Solution::format_license_key("2-4A0r7-4k", 4),
        Ok("24A0-R74K".to_string())
    );
}

