impl MinHeap {
    fn find_smaller_child(&self, index: usize) -> Option<usize> {
        let left_child_index = 2 * index + 1;
        let right_child_index = 2 * index + 2;
        // No right child
        if right_child_index >= self.array.len() {
            // No left child
            if left_child_index >= self.array.len() {
                return None;
            }
            // Left child only
            return Some(left_child_index);
        }
        // Compare left and right children
        if self.array[left_child_index] < self.array[right_child_index] {
            Some(left_child_index)
        } else {
            Some(right_child_index)
        }
    }
}

#[test]
fn test_min_heap() {
    let mut heap = MinHeap::new();
    assert_eq!(heap.peek_min(), None);
    assert_eq!(heap.extract_min(), None);
    heap.insert(20);
    assert_eq!(heap.array[0], 20);
    heap.insert(5);
    assert_eq!(heap.array[0], 5);
    assert_eq!(heap.array[1], 20);
    heap.insert(15);
    assert_eq!(heap.array[0], 5);
    assert_eq!(heap.array[1], 20);
    assert_eq!(heap.array[2], 15);
    heap.insert(22);
    assert_eq!(heap.array[0], 5);
    assert_eq!(heap.array[1], 20);
    assert_eq!(heap.array[2], 15);
    assert_eq!(heap.array[3], 22);
    heap.insert(40);
    assert_eq!(heap.array[0], 5);
    assert_eq!(heap.array[1], 20);
    assert_eq!(heap.array[2], 15);
    assert_eq!(heap.array[3], 22);
    assert_eq!(heap.array[4], 40);
    heap.insert(3);
    assert_eq!(heap.array[0], 3);
    assert_eq!(heap.array[1], 20);
    assert_eq!(heap.array[2], 5);
    assert_eq!(heap.array[3], 22);
    assert_eq!(heap.array[4], 40);
    assert_eq!(heap.array[5], 15);
    let mut mins = Vec::new();
    while !heap.is_empty() {
        mins.push(heap.extract_min().unwrap());
    }
    assert_eq!(mins, vec![3, 5, 15, 20, 22, 40]);
}
